                            key=(
                                aas.Key(
                                    type_=aas.KeyTypes.GLOBAL_REFERENCE,
                                    value=r"https://www.w3.org/2019/wot/security#NoSecurityScheme",
                                ),
                            ),
                            referred_semantic_id=None,
