                    def __init__(
                        self,
                        scheme: Union[str, Scheme],
                        name: Optional[Union[str, Name]] = None,
                        in_: Optional[Union[str, In]] = None,
                        authorization: Optional[Union[str, Authorization]] = None,
                        alg: Optional[Union[str, Alg]] = None,
                        format: Optional[Union[str, Format]] = None,
                        proxy: Optional[Union[str, Proxy]] = None,
                        id_short: Optional[str] = r"bearer_sc",
                        display_name: Optional[
                            aas.MultiLanguageNameType
                        ] = aas.MultiLanguageNameType(dict_={r"en": r"Bearer Sc"}),
                        category: Optional[str] = None,
                        description: Optional[
                            aas.MultiLanguageTextType
                        ] = aas.MultiLanguageTextType(
                            dict_={
                                r"en": r"This SubmodelElements holds the information about security mechanism based on bearer security."
                            }
                        ),
                        semantic_id: Optional[aas.Reference] = aas.ExternalReference(
                            key=(
                                aas.Key(
                                    type_=aas.KeyTypes.GLOBAL_REFERENCE,
                                    value=r"https://www.w3.org/2019/wot/security#BearerSecurityScheme",
                                ),
                            ),
                            referred_semantic_id=None,
                        ),
                        qualifier: Iterable[aas.Qualifier] = None,
                        extension: Iterable[aas.Extension] = (),
                        supplemental_semantic_id: Iterable[aas.Reference] = (),
                        embedded_data_specifications: Iterable[
                            aas.EmbeddedDataSpecification
                        ] = None,
                    ):

                        if qualifier is None:
                            qualifier = (
                                aas.Qualifier(
                                    type_=r"Cardinality",
                                    value_type=str,
                                    value=r"ZeroToOne",
                                    value_id=None,
                                    kind=aas.QualifierKind.CONCEPT_QUALIFIER,
                                    semantic_id=None,
                                    supplemental_semantic_id=(),
                                ),
                            )

                        if embedded_data_specifications is None:
                            embedded_data_specifications = []

                        # Build a submodel element if a raw value was passed in the argument

                        if scheme is not None and not isinstance(
                            scheme, aas.SubmodelElement
                        ):
                            scheme = self.Scheme(scheme)

                        # Build a submodel element if a raw value was passed in the argument

                        if name is not None and not isinstance(
                            name, aas.SubmodelElement
                        ):
                            name = self.Name(name)

                        # Build a submodel element if a raw value was passed in the argument

                        if in_ is not None and not isinstance(in_, aas.SubmodelElement):
                            in_ = self.In(in_)

                        # Build a submodel element if a raw value was passed in the argument

                        if authorization is not None and not isinstance(
                            authorization, aas.SubmodelElement
                        ):
                            authorization = self.Authorization(authorization)

                        # Build a submodel element if a raw value was passed in the argument

                        if alg is not None and not isinstance(alg, aas.SubmodelElement):
                            alg = self.Alg(alg)

                        # Build a submodel element if a raw value was passed in the argument

                        if format is not None and not isinstance(
                            format, aas.SubmodelElement
                        ):
                            format = self.Format(format)

                        # Build a submodel element if a raw value was passed in the argument

                        if proxy is not None and not isinstance(
                            proxy, aas.SubmodelElement
                        ):
                            proxy = self.Proxy(proxy)

                        # Add all passed/initialized submodel elements to a single list
                        embedded_submodel_elements = []
                        for se_arg in [
                            scheme,
                            name,
                            in_,
                            authorization,
                            alg,
                            format,
                            proxy,
                        ]:
                            if se_arg is None:
                                continue
                            elif isinstance(se_arg, aas.SubmodelElement):
                                embedded_submodel_elements.append(se_arg)
                            elif isinstance(se_arg, Iterable):
                                for n, element in enumerate(se_arg):
                                    element.id_short = f"{element.id_short}{n}"
                                    embedded_submodel_elements.append(element)
                            else:
                                raise TypeError(
                                    f"Unknown type of value in submodel_element_args: {se_arg.__class__}"
                                )

                        super().__init__(
                            value=embedded_submodel_elements,
                            id_short=id_short,
                            display_name=display_name,
                            category=category,
                            description=description,
                            semantic_id=semantic_id,
                            qualifier=qualifier,
                            extension=extension,
                            supplemental_semantic_id=supplemental_semantic_id,
                            embedded_data_specifications=embedded_data_specifications,
                        )

